  SELECT id, 12, 0, $h12$الفصل الثاني - التأسيس والترخيص والقيد بالسجل - ثانياً - قيد الأشخاص الطبيعيين في السجل$h12$, $t12_0$المادة الثانية عشرة - إجراءات قيد أو تجديد قيد أو إعادة قيد الأشخاص الطبيعيين بالسجل$t12_0$, $b12_0$يقدم طلب القيد أو تجديد القيد أو إعادة القيد بالسجل على النموذج المعد لهذا الغرض لدى الهيئة مرفقاً به البيانات والمستندات الآتية :
أولاً - بالنسبة للمصريين
1- صورة من بطاقة الرقم القومي .
2- شهادة المؤهل الدراسي .
3- شهادة اجتياز البرنامج التدريبي لدى الجهة المعتمدة من الهيئة .
4- شهادة اجتياز الاختبارات التي تعقدها الهيئة في هذا الشأن .
5- صحيفة حالة جنائية حديثة .
6- شهادة تفيد عدم صدور أحكام بإشهار الإفلاس .
7- شهادة تفيد عدم صدور أحكام حجر عن الخمس سنوات السابقة على تاريخ تقديم الطلب .
8- تعهد بالتسجيل على المنصة الإلكترونية للمهنيين .
9- إقرار بألا يكون قد فصل من عمله بحكم أو بقرار تأديبي نهائي أو صدر قرار بشطب اسمه من سجل المهن التي تنظمها القوانين واللوائح لأمور تمس الأمانة أو الشرف ما لم يمض على ذلك ثلاث سنوات .
10- وثيقة تأمين مسئولية مهنية على النحو الوارد بهذا القرار .
11- المستند الدال على سداد الرسم المقرر وفقاً لقرار مجلس إدارة الهيئة الصادر في هذا الشأن .
12- بالنسبة لخبراء التأمين الاستشاريين الذي يعملون لدى شركات الخبرة الاستشارية في مجال التأمين فيشترط تقديم المستندات الآتية :
(أ) خطاب صادر من الشركة يفيد بأن طالب القيد ، أو تجديد القيد ، أو إعادة القيد من العاملين لديها ، أو سيتم إلحاقه للعمل بها .
(ب) تعهد من الشركة بإخطار الهيئة بأي مخالفة تنسب إلى الخبير أو أي تغيير أو تعديل في بيانات حالته الوظيفية بالشركة .
(ج) إقرار على مطبوعات الشركة بما يفيد مراجعتها لجميع المستندات الخاصة بطالب القيد أو تجديد القيد أو إعادة القيد التابع لها ، وأنها تحت مسئوليتها ، وختمها بخاتمها .
(د) تعهد من طالب القيد بعدم العمل لدى شركة أخرى في ذات الوقت .
ثانياً - بالنسبة للأجانب
1- تقديم المستندات المشار إليها بالبنود (2 ، 3 ، 4 ، 8 ، 9 ، 10 ، 11 ، 12) أعلاه .
2- صورة من جواز السفر .
3- تصريح الإقامة والعمل في مصر .
4- إقرار بما تضمنه البندان (5 ، 6) أعلاه .
ويجوز قيد خبير التأمين الاستشاري الطبيعي الأجنبي غير المقيم في مصر أو تجديد أو إعادة قيده بالسجل ، شريطة استيفاء ما يلي :
5- أن يكون مرخصاً له بمزاولة النشاط من جهة رقابية تمارس اختصاصات مثيلة للهيئة في مجال التأمين .
6- ألا يكون قد صدر ضده تدابير من الجهة الرقابية الخاضعة لها خلال الثلاث سنوات السابقة على طلب القيد .
7- تقديم المستندات المشار إليها بالبنود (2 ، 3 ، 4 ، 8 ، 9 ، 10 ، 11 ، 12) أعلاه .
8- تقديم صورة من جواز السفر .
9- تقديم إقرار بما تضمنه البندان (5 ، 6) أعلاه .
وفي جميع الأحوال ، يجوز للهيئة طلب أي بيانات أو مستندات أخرى ترى ضرورة تقديمها للبت في الطلب .
وتبت الهيئة في الطلب خلال ثلاثين يوماً على الأكثر من تاريخ تقديمه مستوفياً المستندات المتطلبة للبت فيه .$b12_0$
  FROM laws WHERE law_no = 25 AND law_year = 2026 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2026-02-25', 'active' FROM ins12_0;

WITH ins13_0 AS (
