WITH ins20_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 20, 0, $h20$الفصل الثالث - قواعد مزاولة نشاط أعمال الخبرة الاستشارية في مجال التأمين والتزامات خبراء التأمين الاستشاريين$h20$, $t20_0$المادة العشرون - مواعيد إعداد وعرض وتقديم القوائم المالية والمستندات المرفقة بها للهيئة$t20_0$, $b20_0$يتعين على الشركة موافاة الهيئة قبل شهر على الأقل من موعد انعقاد الجمعية العامة بالقوائم المالية السنوية والإفصاحات المرفقة بها وفقاً لمعايير المحاسبة المصرية ، وتقرير بشأنها من أحد مراقبي الحسابات المقيدين بالقسم الأول من سجل مراقبي الحسابات المنظم بقرار مجلس إدارة الهيئة رقم (244) لسنة 2023 المشار إليه ، وتقرير مجلس الإدارة عن نشاط الشركة ، وموعد ومكان انعقاد الجمعية العامة وجدول أعمالها ، وجميع المستندات التي تقدم إلى المساهمين عن أعمال الشركة .
وللهيئة إبداء ملاحظاتها على القوائم المالية ، وكذا على أي من البيانات والمستندات الواردة بهذا القرار وإخطار الشركة بملاحظاتها ، على أن يعرض ذلك على الجمعية العامة للشركة .
وتلتزم الشركة بموافاة الهيئة بالقوائم المالية السنوية لها خلال خمسة وأربعين يوماً من تاريخ انتهاء الثلاثة أشهر التالية لانتهاء السنة المالية مرفقاً بها المستندات الآتية :
1- تقرير مراقب الحسابات عن تلك القوائم حال تعديلها من قبل الجمعية العامة للشركة .
2- بيان بالاستشارات التأمينية التي أجرتها خلال العام .
3- بيان بعملائها الذين تعاملت معهم خلال السنة المالية المنقضية وبيان بإيراداتها المستحقة والمحصلة عن الاستشارات التأمينية التي قامت بإجرائها لكل عميل على حدة عن السنة المالية المنقضية موزعاً على كل فرع تأميني ولإجمالي الفروع .$b20_0$
  FROM laws WHERE law_no = 25 AND law_year = 2026 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2026-02-25', 'active' FROM ins20_0;

WITH ins21_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 21, 0, $h21$الفصل الثالث - قواعد مزاولة نشاط أعمال الخبرة الاستشارية في مجال التأمين والتزامات خبراء التأمين الاستشاريين$h21$, $t21_0$المادة الحادية والعشرون - السجلات التي يتعين على خبراء التأمين الاستشاريين إمساكها$t21_0$, $b21_0$يتعين على خبراء التأمين الاستشاريين إمساك السجلات الآتية :
أولاً - سجل الاستشارات :
ويقيد به بيانات جميع الاستشارات التأمينية التى قام الخبير بإجرائها ، ويتضمن – بحد أدنى – البيانات الآتية :
1- اسم العميل وعنوانه .
2- فرع التأمين محل الاستشارة .
3- تاريخ التكليف بالاستشارة التأمينية ، وتاريخ تقديمها إلى العميل .
4- نوع الاستشارة ، سواء كانت متعلقة بإصدار أو تعويض أو تجديد أو إعادة تقييم أو مراجعة وثائق سارية أو غير ذلك .
5- اسم الخبير التابع لشركة الخبرة الذي قام بإجراء الاستشارة التأمينية .
6- الأتعاب أو المقابل الذي حصل عليه الخبير الذي قام بإجراء الاستشارة التأمينية .
7- أي بيانات أخرى تطلبها الهيئة .
ثانياً - سجل الخبراء (بالنسبة لشركات الخبرة الاستشارية في مجال التأمين) :
ويقيد به بيانات كل خبير تأمين استشاري التحق بالعمل لدى الشركة ، ويتضمن - بحد أدنى - البيانات الآتية :
1- اسم الخبير ، ونوعه ، وجنسيته ، ورقمه القومي ، وعنوان محل إقامته .
2- رقم وتاريخ قيده ، وتاريخ آخر تجديد قيد أو إعادة قيد لدى الهيئة .
3- تاريخ التحاقه بالعمل لدى الشركة وأي تغييرات طرأت على حالته بالشركة .
4- التدابير السابق توقيعها ضده (حال وجودها) .
5- أي بيانات أخرى تطلبها الهيئة .
ثالثاً - أي سجلات أخرى تحددها الهيئة :$b21_0$
  FROM laws WHERE law_no = 25 AND law_year = 2026 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2026-02-25', 'active' FROM ins21_0;

WITH ins22_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 22, 0, $h22$الفصل الثالث - قواعد مزاولة نشاط أعمال الخبرة الاستشارية في مجال التأمين والتزامات خبراء التأمين الاستشاريين$h22$, $t22_0$المادة الثانية والعشرون - التزامات خبراء التأمين الاستشاريين$t22_0$, $b22_0$يجب على خبير التأمين الاستشاري مراعاة مبادئ النزاهة والاستقامة والأمانة والعدالة وحسن التصرف وبذل عناية الرجل الحريص في جميع أعماله وتصرفاته والامتناع عن القيام بأي فعل ينطوي على إساءة إلى غيره من الخبراء أو العملاء أو منشآت التأمين وإعادة التأمين أو مهنة الخبرة الاستشارية في مجال التأمين بوجه عام .
ويتعين على خبير التأمين الاستشاري مباشرة أعمال الخبرة الاستشارية في مجال التأمين وفقاً لأحكام قانون التأمين الموحد والقرارات الصادرة تنفيذاً له ، وذلك مع الالتزام - بحد أدنى – بالضوابط الآتية :
1- أن يكون على علم ووعي بالتشريعات التأمينية والقواعد المنظمة للسوق وكذا القرارات الصادرة عن الهيئة ومتابعة ما يطرأ عليها من تعديلات والعمل على تطبيقها بدقة وعدم مخالفتها .
2- الإشارة إلى أنه "خبير تأمين استشاري" في أي عمل من أعماله ، وأن يقرن اسمه برقم قيده في السجل ، وذلك في جميع المكاتبات والشهادات والتقارير الصادرة عنه .
3- تجنب تعارض المصالح والإفصاح عنه فور العلم به للمتعاملين معه وذوي الشأن .
4- الحفاظ على سرية البيانات وخصوصية المعلومات التي يطلع عليها ، وعدم نشرها أو استخدامها خارج نطاق المهمة المكلف بها .
5- التعاون مع المحاكم أو الجهة المختصة وتقديم الإيضاحات عند طلبها .
6- الحياد والموضوعية وعدم الانحياز لأي طرف من أطراف النزاع عند إعداد تقرير للعرض على المحاكم المختصة أو هيئات التحكيم أو غير ذلك .
7- الامتناع عن الحصول على أي امتيازات مالية أو عينية غير معلنة سواء من عملائه أو من غيرهم .
8- توثيق مصادر المعلومات والمستندات التي بنى عليها الرأي والامتناع عن إبداء الرأي خارج حدود خبرته أو دون معلومات كافية .
9- استخدام الأساليب العلمية السليمة عند إبداء الرأي وأن يكون واضحاً ومسبباً ومبنياً على وقائع وأدلة محددة ، وعدم الاعتماد على التخمين أو الافتراضات غير الموثقة .
10- مراعاة الضوابط الخاصة بمكافحة غسل الأموال وتمويل الإرهاب وانتشار التسلح وفقاً للتشريعات الصادرة في هذا الشأن .
11- الاحتفاظ بجميع المستندات والعقود التي تم إبرامها مع منشآت التأمين لتقديم خدمات استشارية لها .
12- الامتناع عن القيام بأي عمل من شأنه تضليل أو الإضرار بأي من المتعاملين معه أو العاملين بقطاع التأمين أو الإخلال بحقوقهم .
13- إخطار الهيئة بالدعاوى القضائية أو التحكيمية التي يكون طرفاً فيها وتتعلق بممارسة نشاطه .
14- موافاة الهيئة بأي بيانات أو مستندات أو سجلات تخص مزاولة النشاط ، متى طلب منه ذلك .$b22_0$
  FROM laws WHERE law_no = 25 AND law_year = 2026 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2026-02-25', 'active' FROM ins22_0;

WITH ins23_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 23, 0, $h23$الفصل الثالث - قواعد مزاولة نشاط أعمال الخبرة الاستشارية في مجال التأمين والتزامات خبراء التأمين الاستشاريين$h23$, $t23_0$المادة الثالثة والعشرون - التزامات منشآت التأمين وإعادة التأمين$t23_0$, $b23_0$يتعين على منشآت التأمين وإعادة التأمين حال تعاملها مع أي خبير تأمين استشارى مراعاة ما يلي :
1- إخطار الهيئة بكل مخالفة تنسب إلى خبير التأمين الاستشاري ، وكذا كل دعوى قضائية أو تحكيمية يكون طرفاً فيها وتتعلق بممارسة نشاطه .
2- موافاة الهيئة سنوياً خلال ثلاثين يوماً على الأكثر من تاريخ انتهاء السنة المالية ببيان موضحاً به حجم أعمال خبراء التأمين الاستشاريين (شخص طبيعي أو اعتباري) التي تمت لديها خلال السنة المنقضية ، وذلك وفقاً للنموذج المعد لهذا الغرض لدى الهيئة .
ويحظر على منشآت التأمين وإعادة التأمين عند تعاملها مع خبراء التأمين الاستشاريين ما يلي :
1- إسناد أي استشارة تأمينية محلية إلى أي خبير ما لم يكن مقيداً لدى الهيئة أو إلى أي خبير تربطه صلة قرابة حتى الدرجة الثانية مع أي من أعضاء مجلس إدارة الشركة أو مع أي من مساهميها أو يوجد مع أي منهم أية مصالح أو نفع مشترك .
2- مشاركة أي من العاملين أو أعضاء مجالس إدارة هذه الشركات في تأسيس أو إدارة أي من شركات خبرة الاستشارات التأمينية .$b23_0$
  FROM laws WHERE law_no = 25 AND law_year = 2026 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2026-02-25', 'active' FROM ins23_0;

WITH ins24_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 24, 0, $h24$الفصل الرابع - إيقاف القيد والتدابير الإدارية$h24$, $t24_0$المادة الرابعة والعشرون - إيقاف قيد خبير التأمين الاستشاري$t24_0$, $b24_0$يتعين على شركات الخبرة الاستشارية إخطار الهيئة حال إنهاء خدمة أي من خبراء التأمين الاستشاريين العاملين لديها ، وذلك خلال أسبوع من تاريخ إنهاء الخدمة ، وتكون الشركة مسئولة عن جميع المخالفات المنسوبة إلى الخبير لحين إخطار الهيئة بإنهاء خدمته وأسباب ذلك .
ويتم إيقاف قيد الخبير بالسجل مؤقتاً فور ورود إخطار الشركة بإنهاء عمله ، ما لم يكن إنهاء العمل بسبب مخالفات تتعلق باستشارات تأمينية أسندت إليه فتقوم الهيئة باتخاذ الإجراءات المقررة بشأن تلك المخالفات وفقاً لأحكام قانون التأمين الموحد والقرارات الصادرة تنفيذاً له .
ولا يجوز للخبير خلال فترة إيقاف قيده ممارسة أي من أعمال الخبرة الاستشارية في مجال التأمين إلا بعد إزالة أسباب إيقاف قيده وانتهاء مدة هذا الإيقاف أو التقدم إلى الهيئة بطلب لتعديل بيانات قيده بالسجل ، واستيفاء أي شروط متطلبة لذلك . ويشطب خبير التأمين الاستشاري من السجل حال انتهاء مدة قيده دون قيامه بتعديل بياناته .$b24_0$
  FROM laws WHERE law_no = 25 AND law_year = 2026 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2026-02-25', 'active' FROM ins24_0;

