  SELECT id, 25, 0, $h25$الفصل الرابع - إيقاف القيد والتدابير الإدارية$h25$, $t25_0$المادة الخامسة والعشرون - التدابير الإدارية$t25_0$, $b25_0$للهيئة حال مخالفة خبير التأمين الاستشاري للقواعد الواردة بهذا القرار اتخاذ أي من التدابير الآتية :
1- الإنذار .
2- إلغاء الموافقة على فتح مكتب لمزاولة أعمال الخبرة الاستشارية في مجال التأمين للأشخاص الطبيعيين أو الفرع للأشخاص الاعتبارية (إذا كان لديه فرع) .
ولمجلس إدارة الهيئة إيقاف قيد خبير التأمين الاستشاري الاعتباري أو الطبيعي لمدة لا تجاوز ثلاث سنوات أو شطب قيده من السجل في حالة فقده أحد شروط التأسيس أو الترخيص أو القيد بالسجل حسب الأحوال ، كما يجوز لمجلس إدارة الهيئة اتخاذ ذات التدبير بعد إجراء تحقيق من قبل الهيئة في أي من الحالات الآتية :
1- إذا ثبت تقديمه أي بيانات جوهرية غير صحيحة مطلوبة وفقاً لأحكام قانون التأمين الموحد أو القرارات ذات الصلة نتيجة تعمد أو خطأ جسيم
2- عدم التزامه بالقواعد والمعايير المهنية اللازمة لمزاولة المهنة .
3- إذا ثبت قيامه بأعمال مخالفة للقوانين أو اللوائح المتعلقة بمهنته أو تنطوي على غش أو خطأ جسيم.$b25_0$
  FROM laws WHERE law_no = 25 AND law_year = 2026 AND kind = 'board_decision'
