DO $verify157$
DECLARE
  v_law_id uuid;
  v_n int; v_v int; v_bad int; v_len int;
BEGIN
  SELECT id INTO v_law_id FROM laws WHERE law_no = 25 AND law_year = 2026 AND kind = 'board_decision';
  IF v_law_id IS NULL THEN
    RAISE WARNING '[157] القرار 25/2026 غير موجود — لا تحقق';
    RETURN;
  END IF;
  SELECT count(*), COALESCE(sum(length(body)), 0) INTO v_n, v_len FROM articles WHERE law_id = v_law_id;
  IF v_n <> 28 THEN RAISE EXCEPTION '[157] عدد المواد % بدل 28', v_n; END IF;
  SELECT count(*) INTO v_v FROM article_versions av JOIN articles a ON a.id = av.article_id WHERE a.law_id = v_law_id AND av.version_no = 1 AND av.status = 'active' AND av.effective_from = DATE '2026-02-25';
  IF v_v <> 28 THEN RAISE EXCEPTION '[157] عدد النسخ % بدل 28', v_v; END IF;
  SELECT count(*) INTO v_bad FROM articles WHERE law_id = v_law_id AND (body ~ '[٠-٩۰-۹]' OR body ~ '[ٌ-ْ]' OR body LIKE '%' || chr(65533) || '%' OR body LIKE '%ـ%' OR body LIKE '%صورة إ%' OR body LIKE '%ة ال يع%' OR body LIKE '%الوقائع المصریة%' OR body LIKE '%الوقائع المصرية –%' OR body LIKE '%الفصل الثاني%' OR body LIKE '%الفصل الثالث%' OR body LIKE '%الفصل الرابع%' OR body LIKE '%الفصل الأول%' OR body LIKE '%12 ، 11%' OR body LIKE '%ت نسب%' OR body LIKE '%ي نشر%' OR body LIKE '%وي عمل%' OR body LIKE '%وي قيد%' OR body LIKE '%وي حظر%' OR body LIKE '%وي شطب%' OR body LIKE '%وي نشر%' OR body LIKE '%ي عرض%' OR body LIKE '%الم عد%' OR body LIKE '%ساري ا%');
